I've just finished writing a unit test to better explain the issue.  Maybe this has something to do with the fact that `DefaultSpdyHeaders` uses a `LinkedHashMap` implementation while `DefaultHttpHeaders` uses a `TreeMap`?

``` java
import io.netty.handler.codec.http.DefaultHttpHeaders;
import io.netty.handler.codec.http.HttpHeaderNames;
import io.netty.handler.codec.http.HttpHeaders;
import io.netty.handler.codec.spdy.DefaultSpdyHeaders;
import io.netty.handler.codec.spdy.SpdyHeaders;
import junit.framework.Assert;
import org.junit.Test;

public class HeadersTest
{
   @Test
   public void testHttpHeaders() throws Exception
   {
      final HttpHeaders headers = new DefaultHttpHeaders(false);

      // Test adding String key
      final String connection = "keep-alive";
      headers.add("Connection", connection);

      // Passes
      final String value = headers.getAndConvert(HttpHeaderNames.CONNECTION.toString());
      Assert.assertNotNull(value);
      Assert.assertEquals(connection, value);

      // Passes
      final String value2 = headers.getAndConvert(HttpHeaderNames.CONNECTION);
      Assert.assertNotNull(value2);
      Assert.assertEquals(connection, value2);

      // Test adding AsciiString key
      final String cacheControl = "no-cache";
      headers.add(HttpHeaderNames.CACHE_CONTROL, cacheControl);

      // Passes
      final String value3 = headers.getAndConvert(HttpHeaderNames.CACHE_CONTROL);
      Assert.assertNotNull(value3);
      Assert.assertEquals(cacheControl, value3);

      // Passes
      final String value4 = headers.getAndConvert(HttpHeaderNames.CACHE_CONTROL.toString());
      Assert.assertNotNull(value4);
      Assert.assertEquals(cacheControl, value4);
   }

   @Test
   public void testSpdyHeaders() throws Exception
   {
      final SpdyHeaders headers = new DefaultSpdyHeaders();

      // Test adding String key
      final String method = "GET";
      headers.add(":method", method);

      // Passes
      final String value = headers.getAndConvert(SpdyHeaders.HttpNames.METHOD.toString());
      Assert.assertNotNull(value);
      Assert.assertEquals(method, value);

      // Should also pass, but doesn't!
      final String value2 = headers.getAndConvert(SpdyHeaders.HttpNames.METHOD);
      Assert.assertNotNull(value2);
      Assert.assertEquals(method, value2);

      // Test adding AsciiString key
      final String path = "/";
      headers.add(SpdyHeaders.HttpNames.PATH, path);

      // Passes
      final String value3 = headers.getAndConvert(SpdyHeaders.HttpNames.PATH);
      Assert.assertNotNull(value3);
      Assert.assertEquals(path, value3);

      // Should also pass, but doesn't!
      final String value4 = headers.getAndConvert(SpdyHeaders.HttpNames.PATH.toString());
      Assert.assertNotNull(value4);
      Assert.assertEquals(path, value4);
   }
}
```
